// Üretilen dosya: tool/ozgun/uret.py. Fizik ve Astronomi · Basit harmonik hareket, evrensel kütleçekim, Kepler yasaları ve uydu yörüngeleri (yay-sarkaç periyodu, kaçış hızı, yer eşzamanlı yörünge) (kolay).
const ozPhysics16Kolay = <(String, String, List<String>, String)>[
  ('Sürtünmesiz yatay rayda K ve L noktaları arasında basit harmonik hareket yapan bir kızağın, tam denge merkezi O noktasından geçerken ivme ve hız büyüklükleri hangi durumu sergiler?', 'İvmesi sıfır olurken sürati en büyük değere ulaşır', ['Hem ivmesi hem de sürati en büyük değerini alır', 'Sürati sıfırlanırken ivmesi maksimum düzeye çıkar', 'İvmesi ve sürati aynı anda sıfır değerine iner'], 'Denge konumunda uzanım sıfır olduğundan net geri çağırıcı kuvvet ve ivme sıfırdır; tüm mekanik enerji kinetik enerjiye dönüştüğü için hız maksimumdur.'),
  ('Düzgün çembersel hareket yapan bir diskin kenarına dik saplanmış çivinin, paralel ışık demeti altında perde üzerine düşen gölgesi incelenmektedir. Çemberin yarıçapı R iken gölgenin yaptığı basit harmonik harekette genlik neye eşittir?', 'Diskin yarıçapı olan R uzunluğuna', ['Diskin çapına karşılık gelen 2R uzunluğuna', 'Çember çevresinin yarısı olan pi çarpı R değerine', 'Yarıçapın karekök ikide biri olan R bölü kök ikiye'], 'Düzgün çembersel hareketin çap üzerindeki izdüşümü basit harmonik harekettir ve maksimum uzanım (genlik) çemberin yarıçapı R kadardır.'),
  ('Laboratuvarda esnek bir cetvelin ucuna yapıştırılan silgi, denge hizasından 6 cm aşağı çekilip bırakıldığında düşeyde simetrik salınım yapıyor. Silginin bir tam periyotluk sürede katettiği toplam yol kaç santimetredir?', 'Yirmi dört santimetrelik toplam yörünge uzunluğu', ['On iki santimetrelik uçtan uca mesafe', 'Altı santimetrelik maksimum ayrılma miktarı', 'Otuz altı santimetrelik salınım güzergâhı'], 'Genliği A = 6 cm olan bir harmonik salınımda cisim bir tam periyotta 4A kadar yol alır; 4 x 6 = 24 cm bulunur.'),
  ('Basit harmonik salınım gerçekleştiren noktasal bir parçacığın herhangi bir t anındaki konum vektörü ile geri çağırıcı kuvvet vektörü arasındaki açısal ilişki nasıldır?', 'Her zaman birbirine zıt yönlü olup aralarında 180 derece vardır', ['Daima aynı yönlü olup aralarındaki açı sıfır derecedir', 'Yalnızca denge konumuna yaklaşırken aynı yönü gösterirler', 'Birbirine dik doğrultuda kalarak 90 derecelik açı yaparlar'], 'Uzanım vektörü denge noktasından cisme doğru çizilirken, geri çağırıcı kuvvet daima cismi denge noktasına çeker; F = -kx gereği hep zıt yönlüdürler.'),
  ('Akustik bir diyapazonun çatal ucu saniyede 440 tam titreşim yaparak havada ses dalgası oluşturmaktadır. Çatal ucunun açısal frekansı radyan/saniye cinsinden hangi ifadeyle hesaplanır?', 'Sekiz yüz seksen pi radyan bölü saniye', ['İki yüz yirmi pi radyan bölü saniye', 'Dört yüz kırk pi radyan bölü saniye', 'Bin yedi yüz altmış pi radyan bölü saniye'], 'Açısal frekans omega = 2 * pi * f bağıntısıyla bulunur. Frekans 440 Hz olduğundan omega = 2 * pi * 440 = 880 pi rad/s olur.'),
  ('Basit harmonik harekette denge noktasından x kadar uzakta bulunan bir cismin anlık hızının büyüklüğünü veren genel cebirsel bağıntı hangisidir (omega: açısal frekans, A: genlik)?', 'Omega çarpı karekök içerisinde A kare eksi x kare', ['Omega kare çarpı parantez içinde A eksi x farkı', 'Omega çarpı karekök içerisinde A kare artı x kare', 'Karekök omega çarpı A kare bölü x ifadesi'], 'Çembersel izdüşüm veya enerji korunumu (1/2 mv^2 + 1/2 kx^2 = 1/2 kA^2) kullanılarak v = omega * karekök(A^2 - x^2) bağıntısı türetilir.'),
  ('Bir metronomun ucundaki kütle dakikada 90 tam salınım yapacak biçimde ayarlanmıştır. Metronom kolunun salınım periyodu kaç saniyedir?', 'Üçte iki saniyelik salınım periyodu', ['Bir buçuk saniyelik tekrarlama süresi', 'Dörtte üç saniyelik titreşim aralığı', 'İkide üç saniyelik tam tur zamanı'], '60 saniyede 90 salınım yapılıyorsa 1 salınım için geçen süre T = 60 / 90 = 2/3 saniyedir.'),
  ('Basit harmonik hareket yapan bir parçacığın ivmesinin büyüklüğü hangi konumda anlık olarak maksimum ivmenin yarısına eşit olur?', 'Uzanım büyüklüğünün genliğin yarısına vardığı noktalarda', ['Denge konumundan genliğin kök ikide biri kadar uzakta', 'Kinetik enerjinin potansiyel enerjiye eşitlendiği hizada', 'Uç noktalara genliğin dörtte biri kadar mesafe kaldığında'], 'İvme büyüklüğü a = omega^2 * |x| ile doğru orantılıdır. a = a_max / 2 olması için |x| = A / 2 olmalıdır.'),
  ('Basit harmonik hareket, kinematik sınıflandırma açısından neden \'sabit ivmeli doğrusal hareket\' denklemleriyle (örneğin x = 1/2 a t^2) doğrudan çözülemez?', 'İvmenin büyüklüğü uzanımla orantılı olarak sürekli değiştiği ve yönü her yarım periyotta ters döndüğü için', ['Cismin izlediği yörünge doğrusal olmayıp her zaman uzayda eğrisel bir parabol çizdiği için', 'Hız vektörünün büyüklüğü tüm salınım boyunca sabit kalıp yalnızca yön değiştirdiği için', 'Net kuvvetin yalnızca uç noktalarda anlık olarak etki edip ara bölgelerde kaybolduğu için'], 'Sabit ivmeli hareket formülleri yalnızca ivmenin zamanla ve konumla değişmediği durumlarda geçerlidir; BHH\'de ise a = -omega^2 * x olup konuma bağlı değişkendir.'),
  ('Bir laboratuvar deneyinde harmonik hareket yapan arabanın ardışık iki durma anı (bir uçtan diğer uca gidişi) kronometre ile 1,8 saniye olarak ölçülüyor. Arabanın frekansı kaç Hertz\'dir?', 'Beş bölü on sekiz Hertz salınım frekansı', ['Beş bölü dokuz Hertz titreşim sıklığı', 'On sekiz bölü beş Hertz tekrarlama değeri', 'Dokuz bölü beş Hertz birim zaman salınımı'], 'Bir uçtan diğer uca gidiş süresi yarım periyottur: T/2 = 1,8 s -> T = 3,6 s = 18/5 s. Frekans f = 1/T = 5/18 Hz bulunur.'),
  ('Harmonik hareket yapan bir parçacığın t1 anında hızı ve ivmesi zıt yönlü, t2 anında ise hızı ve ivmesi aynı yönlü olarak tespit ediliyor. Parçacığın bu iki andaki hareket durumu için hangisi kesinlikle doğrudur?', 't1 anında denge konumundan uzaklaşmakta, t2 anında denge konumuna yaklaşmaktadır', ['t1 anında pozitif bölgede bulunmakta, t2 anında negatif bölgede hareket etmektedir', 't1 anında sürati düzenli artmakta, t2 anında sürati düzenli azalmaktadır', 't1 anında tam denge noktasından geçmekte, t2 anında uç noktadan dönmektedir'], 'Hız ve ivme zıt yönlü ise cisim yavaşlıyordur yani denge merkezinden uca doğru gidiyordur; aynı yönlü ise cisim hızlanıyordur yani uçtan denge merkezine yaklaşıyordur.'),
  ('Düzgün çembersel hareketten basit harmonik hareket elde edilirken, çembersel yörüngedeki merkezcil ivme vektörünün çap üzerindeki dik izdüşümü hangi fiziksel niceliği verir?', 'Harmonik hareketin anlık geri çağırıcı ivmesini', ['Salınım hareketinin ortalama teğetsel hızını', 'Parçacığın birim zamandaki açısal yer değiştirmesini', 'Yörünge boyunca korunan toplam mekanik enerjiyi'], 'Düzgün çembersel harekette merkeze yönelik a_m = omega^2 * R ivmesinin yatay çapa izdüşümü a_x = -omega^2 * R * cos(theta) = -omega^2 * x olup doğrudan BHH ivmesine eşittir.'),
  ('Basit harmonik hareket yapan 2 kg kütleli bir cismin hız-zaman denklemi v(t) = 6 cos(3t) m/s olarak verilmiştir. Bu cismin salınım genliği kaç metredir?', 'İki metrelik maksimum ayrılma mesafesi', ['Üç metrelik uç nokta koordinatı', 'Altı metrelik toplam salınım aralığı', 'Bir buçuk metrelik yarı yörünge boyu'], 'v(t) = v_max * cos(omega*t) denkleminden v_max = 6 m/s ve omega = 3 rad/s okunur. v_max = omega * A bağıntısından A = 6 / 3 = 2 metre bulunur.'),
  ('Sürtünmesiz ortamda basit harmonik hareket yapan bir cismin konum-zaman grafiğinde herhangi bir t anındaki teğetin eğimi sıfır oluyorsa, bu t anında cisim hakkında hangisi doğrudur?', 'Genlik sınırlarından birinde olup geri çağırıcı ivmesi maksimum büyüklüktedir', ['Denge konumundan geçmekte olup net kuvvet anlık olarak sıfırdır', 'Maksimum sürate ulaşmış olup kinetik enerjisi zirve değerdedir', 'Hız vektörü ile ivme vektörü birbirine dik konuma gelmiştir'], 'Konum-zaman grafiğinin teğet eğimi anlık hızı (dx/dt = v) verir. Eğimin sıfır olduğu anlarda hız sıfırdır; bu da cismin uç noktalarda (x = +A veya -A) ve maksimum ivmede olduğunu gösterir.'),
  ('Basit harmonik hareket ile düzgün doğrusal hareket karşılaştırıldığında, hangi fiziksel büyüklüğün tüm hareket boyunca sabit kalması yalnızca basit harmonik harekete (sürtünmesiz ortamda) özgü bir periyodik değişmezliktir?', 'Geri çağırıcı kuvvetin uzanıma oranının negatif işaretle sabit kalması', ['Anlık hız vektörünün yön ve büyüklük bakımından hiç değişmemesi', 'Birim zamanda alınan yolun her zaman diliminde birbirine eşit çıkması', 'Cisme etki eden net kuvvetin tüm yörünge noktalarında sıfır olması'], 'Düzgün doğrusal harekette hız sabittir ve net kuvvet sıfırdır; sürtünmesiz BHH\'de ise F/x = -k (yay/geri çağırıcı sabit) oranı hareket boyunca değişmez bir karakteristiktir.'),
  ('Hoparlör diyaframı 100 Hz frekanslı saf bir ses tonu üretirken basit harmonik hareket yapmaktadır. Diyaframın tam denge konumundan geçtikten sonra ilk kez maksimum ivme büyüklüğüne ulaşması kaç milisaniye sürer?', 'İki buçuk milisaniyelik çeyrek periyot', ['Beş milisaniyelik yarım salınım süresi', 'On milisaniyelik tam dalga periyodu', 'Bir tam yüzde yirmi beş milisaniye'], 'f = 100 Hz ise periyot T = 1/100 s = 10 milisaniyedir. Denge konumundan maksimum ivmeli uç noktaya ilk varış süresi T/4 = 10 / 4 = 2,5 milisaniyedir.'),
  ('Bir mikro-elektromekanik (MEMS) ivmeölçer içindeki silikon kiriş 10 kHz frekansla titreşmektedir. Kirişin açısal frekansı kaç radyan/saniyedir?', 'Yirmi bin pi radyan bölü saniye', ['On bin pi radyan bölü saniye', 'Beş bin pi radyan bölü saniye', 'Kırk bin pi radyan bölü saniye'], 'f = 10 kHz = 10.000 Hz olduğundan omega = 2 * pi * f = 2 * pi * 10.000 = 20.000 pi rad/s bulunur.'),
  ('Harmonik hareket yapan bir cisim denge noktasından geçerken kronometre çalıştırılıyor. Cismin ilk kez geri dönüp başlangıçtaki denge noktasından ilk geçişiyle zıt yönde geçtiği ana kadar geçen süre periyodun kaçta kaçıdır?', 'Periyodun tam yarısına eşit süre', ['Periyodun dörtte birine denk zaman', 'Periyodun dörtte üçü kadar aralık', 'Tam bir periyotluk çevrim süresi'], 'O noktasından +A\'ya gidiş T/4, +A\'dan dönüp tekrar O noktasına zıt yönde geliş bir T/4 daha sürer; toplam geçen süre T/4 + T/4 = T/2 olur.'),
  ('Doğrusal bir yolda x = 2 m noktası ile x = 10 m noktası arasında basit harmonik hareket yapan bir aracın denge merkezinin koordinatı ve salınım genliği sırasıyla nedir?', 'Denge merkezi x = 6 m, genliği ise 4 metredir', ['Denge merkezi x = 5 m, genliği ise 5 metredir', 'Denge merkezi x = 6 m, genliği ise 8 metredir', 'Denge merkezi x = 4 m, genliği ise 6 metredir'], 'Simetrik salınımda denge merkezi uç koordinatların aritmetik ortalamasıdır: x_0 = (2 + 10)/2 = 6 m. Genlik ise merkezden bir uca uzaklıktır: A = 10 - 6 = 4 m.'),
  ('Basit harmonik salınım yapan bir cismin uzanım-zaman grafiği incelendiğinde grafiğin tepe noktalarının sıklığı sabit kalırken tepelerin düşey yüksekliği iki katına çıkmışsa harekette ne değişmiştir?', 'Frekansı değişmemiş ancak salınım genliği iki katına çıkmıştır', ['Periyodu yarıya inmiş ve maksimum ivmesi sabit kalmıştır', 'Hem frekansı hem de açısal hızı iki katına yükselmiştir', 'Genliği sabit kalırken denge noktası yukarı kaymıştır'], 'Uzanım-zaman grafiğinde yatay eksendeki tepe sıklığı frekansı (ve periyodu), düşey eksendeki tepe yüksekliği ise salınım genliğini gösterir.'),
  ('Bir saat sarkacının ucundaki topuz küçük açılarla salınırken en alt nokta olan denge hizasından geçtiği anda ipte oluşan kuvvetlerin bileşkesi hariç, yörüngeye teğet olan geri çağırıcı kuvvet bileşeni ne kadardır?', 'Teğetsel geri çağırıcı kuvvet bileşeni tam olarak sıfırdır', ['Topuzun ağırlığının tamamına eşit büyüklüktedir', 'Maksimum geri çağırıcı kuvvetin yarısı kadardır', 'İpteki gerilme kuvvetinin iki katına eşittir'], 'En alt denge konumunda sarkaç ipi düşeydir; ağırlık ile ip gerilmesi aynı düşey doğrultudadır, yörüngeye teğet doğrultuda uzanım ve açı sıfır olduğundan geri çağırıcı teğetsel kuvvet sıfırdır.'),
  ('Sürtünmesiz yatay düzlemde -15 cm ile +15 cm arasında basit harmonik hareket yapan bir kızağın periyodu 3 saniyedir. Kızak -15 cm noktasından bırakıldıktan 4,5 saniye sonra hangi koordinatta bulunur?', 'Artı on beş santimetre pozitif uç koordinatında', ['Eksi on beş santimetre başlangıç noktasında', 'Sıfır santimetre denge merkezi hizasında', 'Artı yedi buçuk santimetre ara bölmesinde'], '4,5 saniye = 1,5 T = T + T/2 süresine karşılık gelir. -15 cm\'den başlayan kızak 3 saniyede (1T) tekrar -15 cm\'ye döner, kalan 1,5 saniyede (T/2) karşı uç olan +15 cm noktasına varır.'),
  ('Düzgün çembersel hareket yapan referans parçacığının çizgisel sürati 10 m/s ve merkezcil ivmesi 50 m/s^2\'dir. Bu parçacığın çap üzerindeki izdüşümünün yaptığı basit harmonik hareketin açısal frekansı kaç rad/s\'dir?', 'Beş radyan bölü saniye açısal frekans', ['Yirmi beş radyan bölü saniye değer', 'İki tam onda beş radyan bölü saniye', 'Sıfır tam onda iki radyan bölü saniye'], 'İzdüşümün maksimum hızı v_max = 10 m/s ve maksimum ivmesi a_max = 50 m/s^2\'dir. omega = a_max / v_max = 50 / 10 = 5 rad/s olarak hesaplanır.'),
  ('Bir cam sileceğinin bağlantı kolu yatay eksende basit harmonik hareket yaparken maksimum ivmesi 12 m/s^2, genliği ise 0,48 m olarak ölçülüyor. Silecek kolunun açısal frekansı kaç rad/s\'dir?', 'Beş radyan bölü saniye açısal hızı', ['Yirmi beş radyan bölü saniye değeri', 'İki buçuk radyan bölü saniye sıklığı', 'On radyan bölü saniye titreşim hızı'], 'a_max = omega^2 * A bağıntısından 12 = omega^2 * 0,48 -> omega^2 = 12 / 0,48 = 25 -> omega = 5 rad/s bulunur.'),
  ('Basit harmonik harekette geri çağırıcı kuvvetin yaptığı iş, cisim denge noktasından uç noktaya giderken ve uç noktadan denge noktasına dönerken işaretçe nasıldır?', 'Uç noktaya giderken negatif iş yapar, dengeye dönerken pozitif iş yapar', ['Her iki yöndeki harekette de pozitif iş yaparak enerjiyi artırır', 'Her iki yönde de hareket doğrultusuna dik kalarak sıfır iş yapar', 'Uç noktaya giderken pozitif, dengeye dönerken negatif iş yapar'], 'Dengeden uca giderken yer değiştirme ile merkeze yönelik kuvvet zıt yönlü olduğundan iş negatiftir (kinetik enerji azalır); uçtan dengeye dönerken kuvvet ve yer değiştirme aynı yönlü olduğundan iş pozitiftir.'),
  ('Biyomekanik incelemede sinekkuşunun kanat çırpışı saniyede 50 tam salınım yapan basit harmonik hareket olarak modelleniyor. Kanat ucunun ardışık iki kez en yüksek sürate ulaşması arasında geçen süre kaç saniyedir?', 'Sıfır tam yüzde bir saniye aralık', ['Sıfır tam yüzde iki saniye periyot', 'Sıfır tam binde beş saniye çeyrek süre', 'Sıfır tam yüzde dört saniye çift tur'], 'f = 50 Hz ise tam periyot T = 1/50 = 0,02 s\'dir. En yüksek sürate her yarım periyotta (denge noktasından geçişlerde) ulaşılır: T/2 = 0,01 saniyedir.'),
  ('Bir laboratuvar deneyinde özdeş iki oyuncak vagon aynı genlikle yatayda basit harmonik hareket yapmaktadır. Birinci vagonun frekansı ikincinin 3 katı olduğuna göre, birinci vagonun maksimum ivmesi ikincinin maksimum ivmesinin kaç katıdır?', 'Dokuz katına ulaşan maksimum ivme büyüklüğü', ['Üç katına çıkan doğrusal ivme artışı', 'Altı katına varan salınım ivmesi değeri', 'Yirmi yedi katına yükselen ivme şiddeti'], 'a_max = 4 * pi^2 * f^2 * A bağıntısına göre genlik A sabitken maksimum ivme frekansın karesiyle doğru orantılıdır; 3^2 = 9 katına çıkar.'),
  ('Yatay düzlemde -12 cm ile +12 cm arasında basit harmonik hareket yapan bir cismin +6 cm noktasındaki ivme büyüklüğü a1, -9 cm noktasındaki ivme büyüklüğü a2 ise a1/a2 oranı kaçtır?', 'İki bölü üç ivme büyüklük oranı', ['Dört bölü dokuz kareli uzanım oranı', 'Üç bölü dört ters konum oranı', 'Kök üç bölü kök yedi hız oranı'], 'İvme büyüklüğü doğrudan uzanım büyüklüğüyle orantılıdır (|a| = omega^2 * |x|). Genlikten bağımsız olarak a1 / a2 = 6 / 9 = 2/3 bulunur.'),
  ('Sürtünmesiz bir masa üzerinde harmonik hareket yapan diskin uzanımı x = +4 cm iken ivmesi -36 cm/s^2 olarak ölçülüyor. Diskin uzanımı x = -7 cm olduğu anda ivmesi nedir?', 'Artı altmış üç santimetre bölü saniye kare', ['Eksi altmış üç santimetre bölü saniye kare', 'Artı yirmi bir santimetre bölü saniye kare', 'Eksi kırk dokuz santimetre bölü saniye kare'], 'a = -omega^2 * x bağıntısında x = +4 cm için -36 = -omega^2 * 4 -> omega^2 = 9 s^(-2) bulunur. x = -7 cm için a = -9 * (-7) = +63 cm/s^2 olur.'),
  ('Newton\'un evrensel kütleçekim yasasına göre iki noktasal kütle arasındaki çekim kuvvetinin büyüklüğü hangi ifadeyle hesaplanır?', 'G·m₁·m₂ / d²', ['G·m₁·m₂ / d', 'G·(m₁ + m₂) / d²', 'G·m₁·m₂ · d²'], 'Evrensel kütleçekim kuvveti kütlelerin çarpımıyla doğru, aralarındaki uzaklığın karesiyle ters orantılıdır.'),
  ('Evrensel kütleçekim sabiti G\'nin SI birim sistemindeki birimi nedir?', 'N·m² / kg²', ['N·m / kg²', 'N·kg² / m²', 'kg·m² / N'], 'F = G·m₁·m₂/d² bağıntısında G çekildiğinde F·d²/(m₁·m₂) elde edilir ve birimi N·m²/kg² olur.'),
  ('Laboratuvar ortamında burulmalı terazi kullanarak evrensel kütleçekim sabiti G\'nin sayısal değerini ilk kez duyarlı biçimde ölçen bilim insanı kimdir?', 'Henry Cavendish', ['Johannes Kepler', 'Galileo Galilei', 'Tycho Brahe'], 'Henry Cavendish 1798 yılında burulmalı sarkaç düzeneğiyle kütleler arası çekimi ölçerek G sabitini ve Dünya\'nın yoğunluğunu hesaplamıştır.'),
  ('Aralarında d uzaklığı bulunan m ve 4m kütleli iki gök cisminden m kütleli olanın diğerine uyguladığı çekim kuvvetinin büyüklüğü F ise, 4m kütleli olanın m kütleli cisme uyguladığı kuvvetin büyüklüğü nedir?', 'F', ['4F', 'F / 4', '16F'], 'Kütleçekim kuvveti etki-tepki çifti oluşturduğundan kütleler ne olursa olsun iki cismin birbirine uyguladığı kuvvetler eşit büyüklükte ve zıt yönlüdür.'),
  ('Dünya yüzeyindeki bir cismin ağırlığı yaklaşık olarak hangi fiziksel kuvvete eşittir?', 'Dünya\'nın cisme uyguladığı kütleçekim kuvvetine', ['Cismin Güneş etrafındaki merkezcil kuvvetine', 'Atmosferin cisme uyguladığı açık hava basıncı kuvvetine', 'Dünya\'nın kendi ekseni etrafındaki dönüşünden doğan eylemsizlik kuvvetine'], 'Yüzeydeki bir cismin ağırlığı, dönme etkisi ihmal edildiğinde Dünya\'nın o cisme uyguladığı kütleçekim kuvvetinin büyüklüğüdür.'),
  ('Kütlesi M, yarıçapı R olan küresel ve homojen bir gezegenin tam yüzeyindeki kütleçekim ivmesinin büyüklüğü veren bağıntı hangisidir?', 'G·M / R²', ['G·M / R', 'G·M² / R²', '2·G·M / R'], 'Yüzeyde m kütleli cisme etki eden m·g ağırlığı G·M·m/R² çekim kuvvetine eşitlendiğinde g = G·M/R² bulunur.'),
  ('Dünya\'nın kutuplardan basık, ekvatordan şişkin geoit şekline sahip olması nedeniyle deniz seviyesinde ekvatordan kutuplara doğru gidildikçe yerçekimi ivmesi nasıl değişir?', 'Artar', ['Azalır', 'Önce azalır sonra sabit kalır', 'Değişmez'], 'Kutuplar Dünya merkezine ekvatordan daha yakın olduğu ve ayrıca kutuplarda Dünya\'nın dönüşünden kaynaklanan merkezkaç etki bulunmadığı için çekim ivmesi artar.'),
  ('Kepler\'in birinci yasası olan Yörüngeler Yasası\'na göre Güneş sistemindeki her gezegen nasıl bir yörüngede dolanır?', 'Odaklarından birinde Güneş bulunan elips biçimli yörüngede', ['Merkezinde Güneş bulunan kusursuz çember biçimli yörüngede', 'Merkezinde Dünya bulunan eş merkezli küresel yörüngede', 'Tepe noktasında Güneş bulunan parabolik açık yörüngede'], 'Kepler\'in birinci yasasına göre gezegenler, odak noktalarından birinde Güneş\'in yer aldığı eliptik yörüngelerde hareket eder.'),
  ('Bir elipsin basıklık derecesini belirten ve odak noktasının merkeze uzaklığının yarı büyük eksen uzunluğuna oranıyla tanımlanan boyutsuz büyüklüğe ne ad verilir?', 'Dış merkezlik', ['Eylemsizlik momenti', 'Açısal momentum', 'Kütleçekim potansiyeli'], 'Elipsin çemberden ne kadar saptığını gösteren c/a oranına dış merkezlik veya eksantriklik (e) denir; çember için bu değer sıfırdır.'),
  ('Kepler\'in ikinci yasası olan Alanlar Yasası\'na göre Güneş\'i gezegene birleştiren yarıçap vektörü eşit zaman aralıklarında ne yapar?', 'Eşit alanlar tarar', ['Eşit yay uzunlukları tarar', 'Eşit hız değişimleri gösterir', 'Eşit kütleçekim kuvvetleri oluşturur'], 'Alanlar yasasına göre gezegenin konum vektörü, yörüngenin neresinde olursa olsun eşit sürelerde eşit büyüklükte alanlar süpürür.'),
  ('Güneş etrafında eliptik yörüngede dolanan bir gezegenin çizgisel hızı yörüngenin hangi noktasında en büyük değerine ulaşır?', 'Güneş\'e en yakın olduğu günberi (perihel) noktasında', ['Güneş\'ten en uzak olduğu günöte (afel) noktasında', 'Yarı küçük eksenin yörüngeyi kestiği tepe noktasında', 'Yörüngenin odak noktalarının tam orta hizasında'], 'Açısal momentum korunduğu için (m·v·r = sabit) gezegen Güneş\'e en yakın konuma (günberi) geldiğinde çizgisel hızı maksimum olur.'),
  ('Kepler\'in üçüncü yasası olan Periyotlar Yasası\'na göre aynı yıldız etrafında dolanan gezegenler için hangi oran sabittir?', 'R³ / T² oranı', ['R² / T³ oranı', 'R / T² oranı', 'R³ · T² çarpımı'], 'Kepler\'in üçüncü yasasına göre gezegenlerin ortalama yörünge yarıçaplarının (yarı büyük eksen) küpünün dolanım periyotlarının karesine oranı sabittir.'),
  ('Dünya yüzeyinden yukarı doğru çıkıldıkça bir cismin kütlesi ve ağırlığı nasıl değişir?', 'Kütlesi değişmez, ağırlığı azalır', ['Kütlesi azalır, ağırlığı değişmez', 'Hem kütlesi hem ağırlığı azalır', 'Kütlesi artar, ağırlığı azalır'], 'Kütle madde miktarının ölçüsü olup konuma bağlı değildir; ağırlık ise m·g olduğundan yükseldikçe g azaldığı için ağırlık da azalır.'),
  ('Güneş ile Dünya arasındaki ortalama uzaklığa (yaklaşık 150 milyon km) gökbilimde hangi birim adı verilir?', 'Astronomik Birim', ['Işık yılı', 'Parsek', 'Angström'], 'Dünya\'nın Güneş\'e olan ortalama uzaklığı 1 Astronomik Birim (AU / AB) olarak tanımlanır ve Güneş sistemi içi mesafelerde standart birim olarak kullanılır.'),
  ('Ay yüzeyindeki kütleçekim ivmesi Dünya yüzeyindekinin yaklaşık altıda biri kadardır. Dünya\'da kütlesi 60 kg olan bir astronotun Ay yüzeyindeki kütlesi kaç kg\'dır?', '60 kg', ['10 kg', '360 kg', '0 kg'], 'Kütle değişmeyen madde miktarıdır ve çekim ivmesine bağlı değildir; astronotun ağırlığı altıda birine inse de kütlesi yine 60 kg kalır.'),
  ('Kütleçekim kuvveti doğadaki dört temel kuvvetten biridir. Bu kuvvetin menzili ve şiddeti diğer temel kuvvetlerle kıyaslandığında hangisi doğrudur?', 'Menzili sonsuzdur ve dört temel kuvvetin en zayıf olanıdır', ['Menzili atom çekirdeği boyutuyla sınırlıdır ve en güçlü kuvvettir', 'Yalnızca elektrik yüklü cisimler arasında etkili olup kısa menzillidir', 'Menzili sonsuz olup elektromanyetik kuvvetten çok daha şiddetlidir'], 'Kütleçekim kuvveti sonsuz menzilli, daima çekici karakterli ve temel parçacıklar düzeyinde diğer üç temel kuvvetten çok daha zayıf olan kuvvettir.'),
  ('Kütleçekim alanı nasıl bir kuvvet alanıdır ve kapalı bir yörünge boyunca kütleçekim kuvvetinin yaptığı toplam iş nedir?', 'Korunumlu bir alandır ve kapalı yörünge boyunca yapılan toplam iş sıfırdır', ['Korunumsuz bir alandır ve kapalı yörünge boyunca yapılan iş yörünge uzunluğuna bağlıdır', 'Sürtünmeli bir alandır ve kapalı yörüngede yapılan iş daima negatiftir', 'Yalnızca doğrusal yollarda iş yapan ve kapalı yörüngede sonsuz iş üreten alandır'], 'Kütleçekim kuvveti korunumlu (konservatif) bir kuvvettir; yapılan iş yoldan bağımsız olup başlangıç ve bitiş noktası aynı olan kapalı yörüngede sıfırdır.'),
  ('Kütleleri m₁ = 2·10¹⁰ kg ve m₂ = 3·10¹⁰ kg olan iki göktaşı arasındaki uzaklık 10 km\'dir. Evrensel çekim sabiti G = 6,67·10⁻¹¹ N·m²/kg² alınırsa aralarındaki çekim kuvveti yaklaşık kaç N olur?', '400,2 N', ['40,02 N', '4002 N', '4,002 N'], 'Uzaklık d = 10 km = 10⁴ m ⇒ d² = 10⁸ m² olur; F = (6,67·10⁻¹¹ · 6·10²⁰) / 10⁸ = 40,02 · 10¹ = 400,2 N bulunur.'),
  ('Gezegen yüzeyindeki kütleçekim alanı vektörünün yönü her noktada nereye doğrudur?', 'Küresel gezegenin geometrik ve kütle merkezine doğru', ['Gezegen yüzeyinden uzay boşluğuna dik ve dışarı doğru', 'Gezegenin yörünge hareket yönüne teğet doğru', 'Gezegenin kuzey manyetik kutup noktasına doğru'], 'Kütleçekim alanı bir noktasal birim kütleye etki eden çekim kuvveti olarak tanımlanır ve daima çekici olduğundan gezegenin merkezine yöneliktir.'),
  ('İki cisim arasındaki uzaklık 3 katına çıkarıldığında kütleleri sabit kalmak koşuluyla aralarındaki kütleçekim kuvveti nasıl değişir?', 'Dokuzda birine iner', ['Üçte birine iner', 'Üç katına çıkar', 'Altıda birine iner'], 'F = G·m₁·m₂/d² bağıntısına göre uzaklık 3d olduğunda payda 9d² olur ve çekim kuvveti ilk değerinin 1/9\'una düşer.'),
  ('Deniz sularının gün içinde belirli periyotlarla yükselip alçalması olan gelgit (medcezir) olayının oluşmasındaki en baskın fiziksel etken nedir?', 'Ay ve Güneş\'in Dünya üzerindeki farklı noktalara uyguladığı kütleçekim kuvveti farkları', ['Dünya\'nın manyetik alan kutuplarının okyanus akıntılarını itmesi', 'Okyanus tabanındaki tektonik plakaların günlük termal genleşmesi', 'Atmosferdeki alize rüzgarlarının mevsimlik yön değiştirmesi'], 'Dünya\'nın Ay\'a bakan yüzü ile arka yüzü arasındaki uzaklık farkından doğan diferansiyel kütleçekim kuvveti (ve kısmen Güneş\'in çekimi) gelgitleri oluşturur.'),
  ('Kütlesi M olan bir gezegenin merkezinden r uzaklıkta çembersel yörüngede dolanan m kütleli bir uydunun çizgisel yörünge hızını veren bağıntı nedir?', '√(G·M / r)', ['√(2·G·M / r)', 'G·M / r²', '√(G·M·m / r)'], 'Çembersel yörüngede merkezcil kuvvet m·v²/r kütleçekim kuvvetine G·M·m/r² eşitlendiğinde uydunun kütlesi sadeleşir ve v = √(G·M/r) elde edilir.'),
  ('Dünya etrafında aynı çembersel yörüngede peş peşe dolanan 500 kg kütleli küçük bir gözlem uydusu ile 5000 kg kütleli büyük bir haberleşme uydusunun yörünge süratleri karşılaştırıldığında hangisi doğrudur?', 'İki uydunun yörünge süratleri birbirine eşittir', ['Büyük kütleli uydunun sürati küçük olanın √10 katıdır', 'Küçük kütleli uydunun sürati büyük olanın 10 katıdır', 'Büyük kütleli uydu daha yavaş dolanır'], 'Uydu yörünge hızı v = √(G·M_Dünya / r) bağıntısına göre dolanan uydunun kendi kütlesinden bağımsızdır; aynı r yarıçapında süratleri eşittir.'),
  ('Aralarında r uzaklığı bulunan M ve m kütleli iki gök cisminden oluşan sistemin kütleçekim potansiyel enerjisi (sonsuzdaki referans sıfır alındığında) hangi bağıntıyla ifade edilir?', '-G·M·m / r', ['G·M·m / r²', '-G·M·m / r²', 'G·M·m /'], 'Sonsuzda potansiyel enerji sıfır kabul edildiğinde ve kuvvet çekici olduğundan r uzaklığındaki kütleçekim potansiyel enerjisi E_p = -G·M·m / r olur.'),
  ('Kütleçekim potansiyel enerjisi bağıntısındaki eksi (-) işaretinin fiziksel anlamı aşağıdakilerden hangisidir?', 'Sistemin birbirine kütleçekimiyle bağlı olduğunu ve cisimleri sonsuza ayırmak için dışarıdan pozitif iş yapılması gerektiğini gösterir', ['Potansiyel enerjinin vektörel bir büyüklük olup gezegenin merkezine doğru yöneldiğini gösterir', 'Cismin kinetik enerjisinin sıfırdan küçük değerler alabileceğini gösterir', 'Yörünge yarıçapı büyüdükçe potansiyel enerjinin sayısal olarak azaldığını gösterir'], 'Sonsuzda potansiyel enerji sıfır seçildiğinden çekici kuvvet altında birbirine yaklaşan cisimlerin potansiyel enerjisi sıfırın altına düşer ve bağlı sistem oluşur.'),
  ('Kütlesi M olan bir gezegenin merkezinden r uzaklıkta çembersel yörüngede dolanan m kütleli bir uydunun kinetik enerjisi hangi bağıntıya eşittir?', 'G·M·m / (2r)', ['G·M·m / r', '-G·M·m / (2r)', '2·G·M·m / r'], 'Kinetik enerji E_k = (1/2)·m·v² bağıntısında v² = G·M/r yerine yazıldığında E_k = G·M·m / (2r) elde edilir.'),
  ('Bir gök cismini bulunduğu kütleçekim alanından tamamen kurtarıp sonsuza (çekim etkisinin sıfır olduğu varsayılan bölgeye) sıfır son hızla ulaştırabilmek için cisme verilmesi gereken en küçük toplam enerjiye ne ad verilir?', 'Bağlanma enerjisi', ['İyonlaşma enerjisi', 'Eşik enerjisi', 'Durgun kütle enerjisi'], 'Gök cismini çekim alanından koparmak için gereken minimum enerjiye, yani toplam mekanik enerjinin mutlak değerine bağlanma enerjisi denir.'),
  ('Kütlesi M, yarıçapı R olan atmosferi bulunmayan küresel bir gezegenin yüzeyinden fırlatılan cismin gezegenin çekim alanından bir daha geri dönmemek üzere kurtulabilmesi için gereken en küçük fırlatma hızına (kurtulma hızına) ait bağıntı hangisidir?', '√(2·G·M / R)', ['√(G·M / R)', '2·√(G·M / R)', 'G·M / R'], 'Enerji korunumundan (1/2)·m·v_k² - G·M·m/R = 0 yazıldığında m sadeleşir ve kurtulma hızı v_k = √(2·G·M/R) bulunur.'),
  ('Bir gezegenin yüzeyinden fırlatılan 1 tonluk bir uzay sondası ile 10 tonluk bir kargo roketinin gezegenin kütleçekim alanından kurtulma hızları karşılaştırıldığında hangisi doğrudur (hava direnci ihmal edilmektedir)?', 'Kurtulma hızları birbirine eşittir', ['10 tonluk roketin kurtulma hızı √10 kat daha büyüktür', '10 tonluk roketin kurtulma hızı 10 kat daha büyüktür', '1 tonluk sondanın kurtulma hızı daha büyüktür'], 'v_k = √(2·G·M/R) formülünde fırlatılan cismin kütlesi yer almaz; gereken kinetik enerji büyük kütle için artsa da kurtulma hızı aynıdır.'),
  ('Dünya yüzeyindeki belirli bir noktadan bakıldığında gökyüzünde hep aynı konumda hareketsizmiş gibi görünen haberleşme uydularına ne ad verilir?', 'Yer eşzamanlı (jeostasyoner / yer sabit) uydu', ['Kutupsal gözlem uydusu', 'Güneş eşzamanlı uydu', 'Eliptik Molniya uydusu'], 'Dünya\'nın kendi ekseni etrafındaki dönüşüyle aynı periyot ve aynı yönde ekvator düzleminde dolanan uydulara yer sabit (jeostasyoner) uydu denir.'),
  ('Yer sabit (jeostasyoner) bir haberleşme uydusunun Dünya etrafındaki dolanım periyodu yaklaşık kaç saattir?', '24 saat', ['12 saat', '1,5 saat', '720 saat'], 'Uydunun yerdeki bir gözlemciye göre sabit kalabilmesi için Dünya\'nın kendi ekseni etrafındaki dönüş periyoduyla (yaklaşık 24 saat) birebir aynı periyotta dolanması gerekir.'),
  ('Ay\'da atmosfer bulunmamasının (gaz moleküllerinin uzaya kaçmış olmasının) kütleçekim fiziği açısından temel açıklaması nedir?', 'Ay\'ın yüzeyinden kurtulma hızının düşük olması nedeniyle güneş ışığıyla ısınan gaz moleküllerinin ısıl süratlerinin kurtulma hızını aşması', ['Ay\'ın kendi ekseni etrafında hiç dönmemesi nedeniyle gazların uzaya savrulması', 'Dünya\'nın manyetik alanının Ay\'daki tüm gazları kendi atmosferine çekmesi', 'Ay yüzeyindeki kraterlerin gaz moleküllerini kimyasal olarak tamamen emmesi'], 'Ay\'ın kütlesi küçük olduğundan kurtulma hızı yalnızca ~2,4 km/s\'dir; gaz moleküllerinin ısıl hızları zamanla bu eşiği aşarak uzaya kaçmıştır.'),
  ('Dünya etrafında sabit süratle çembersel yörüngede dolanan bir haberleşme uydusu için aşağıdaki ifadelerden hangisi yanlıştır?', 'Uydunun hızı ve ivmesi hareket boyunca sabit vektörlerdir', ['Uydunun kinetik enerjisi hareket boyunca sabittir', 'Uyduya etki eden net kuvvet Dünya\'nın merkezine doğrudur', 'Kütleçekim kuvveti uydu üzerinde hareket boyunca iş yapmaz'], 'Çembersel harekette sürat ve ivme büyüklüğü sabittir ancak hız ve ivme vektörlerinin yönü her an değiştiği için sabit vektör değillerdir.'),
  ('Kutuplardan geçen bir yörünge düzleminde alçak irtifada dolanarak Dünya dönmeye devam ettikçe tüm yeryüzünü şeritler halinde tarayan haritalama ve meteoroloji uydularına ne ad verilir?', 'Kutupsal yörüngeli uydu', ['Yer sabit (jeostasyoner) uydu', 'Lagrange noktası uydusu', 'Jeosenkron ekvator uydusu'], 'Kuzey ve güney kutupları üzerinden geçen dik eğimli yörüngelerde dolanıp Dünya\'nın kendi dönüşü sayesinde tüm yüzeyi görüntüleyen uydulara kutupsal yörüngeli uydular denir.'),
  ('Bir gezegenin çevresindeki eş potansiyel yüzeyler (kütleçekim potansiyelinin her noktasında aynı değere sahip olduğu yüzeyler) ile kütleçekim alan çizgileri arasındaki açı kaç derecedir?', '90° (birbirine daima diktir)', ['0° (birbirine paraleldir)', '45°', '180°'], 'Küresel bir gezegenin eş potansiyel yüzeyleri eş merkezli küre kabuklarıdır; merkeze doğru yönelen kütleçekim alan çizgileri bu küre yüzeylerine her noktada diktir (90°).'),
  ('Bir uydunun Dünya etrafında düşmeden sürekli dolanabilmesini Isaac Newton ünlü düşünce deneyinde nasıl açıklamıştır?', 'Yüksek bir dağın tepesinden yatay fırlatılan top mermisinin yeterince hızlı atıldığında düştüğü miktarın Dünya\'nın yüzey eğriliğiyle tam eşleşmesiyle', ['Belirli bir irtifanın üstünde yerçekimi kuvvetinin yön değiştirerek itici hale gelmesiyle', 'Uzay boşluğundaki eter maddesinin mermiyi alttan kaldırma kuvvetiyle desteklemesiyle', 'Yatay atılan cisimlere hareketleri süresince yerçekimi kuvvetinin etki etmemesiyle'], 'Newton\'un top mermisi düşünce deneyinde yüksek yatay hızla fırlatılan mermi sürekli Dünya\'ya doğru düşer, ancak Dünya\'nın küresel yüzeyi de aynı oranda alçaldığı için mermi yere çarpmadan yörüngeye girer.'),
  ('Bir gezegenin yüzeyinden kurtulma hızı 10 km/s\'dir. Bu gezegenin yüzeyine çok yakın çembersel yörüngede dolanan bir uydunun çizgisel sürati kaç km/s olur?', '5√2 km/s', ['10√2 km/s', '5 km/s', '20 km/s'], 'v_k = √2 · v_y bağıntısından v_y = v_k / √2 = 10 / √2 = 5√2 km/s elde edilir.'),
  ('Ay\'ın Dünya etrafındaki yaklaşık 27,3 günlük dolanım periyodu ile kendi ekseni etrafındaki dönüş periyodunun birbirine eşit olması (kütleçekimsel kilitlenme) hangi gözlemsel sonuca yol açar?', 'Dünya\'dan bakıldığında Ay\'ın her zaman aynı yüzünün görülmesine', ['Ay\'ın gökyüzünde tek bir noktada hiç hareket etmeden sabit durmasına', 'Her gece tam dolunay evresinin gözlemlenmesine', 'Ay yüzeyinde kütleçekim ivmesinin sıfır olmasına'], 'Eşzamanlı dönüş (gelgit kilitlenmesi) nedeniyle Ay Dünya etrafında bir tur atarken kendi etrafında da tam bir tur döner ve Dünya\'ya hep aynı yarım küresi bakar.'),
  ('Bir uydunun çembersel yörüngedeki dolanım periyodu T biliniyorsa, uydunun açısal hızının büyüklüğü (ω) hangi bağıntıyla hesaplanır?', '2π / T', ['2π · T', 'π /', '1 / T²'], 'Bir tam dolanımda taranan radyan cinsinden açı 2π olduğundan sabit açısal hız ω = 2π / T bağıntısıyla bulunur.'),
  ('Dünya yüzeyinden fırlatılan bir uydunun yörüngeye yerleşebilmesi için dikey yükseldikten sonra roket kademeleriyle yatay doğrultuda hızlandırılmasının amacı nedir?', 'Yere düşmeden Dünya etrafında dolanmasını sağlayacak teğetsel yörünge hızını kazandırmak', ['Atmosferin üst katmanlarında paraşüt açarak havada asılı kalmasını sağlamak', 'Dünya\'nın manyetik kutuplarına tutunmasını kolaylaştırmak', 'Uydunun kütlesini azaltarak yerçekimi kuvvetini sıfırlamak'], 'Yalnızca dikey fırlatılan bir araç en tepe noktada durup geri Dünya\'ya düşer; kapalı bir yörüngeye girmek için merkezcil ivmeyi karşılayacak yüksek yatay (teğetsel) yörünge hızı şarttır.'),
  ('Sürtünmesiz yatay düzlemde basit harmonik hareket yapan bir cisim denge konumundan geçerken hangi büyüklüğü sıfır olur?', 'Net geri çağırıcı kuvvet', ['Çizgisel hız büyüklüğü', 'Kinetik enerji değeri', 'Çizgisel momentum büyüklüğü'], 'Denge konumunda uzanım sıfır olduğundan F = -k·x bağıntısına göre geri çağırıcı kuvvet ve ivme sıfırdır.'),
  ('Basit harmonik harekette geri çağırıcı kuvvet vektörünün yönü için aşağıdakilerden hangisi her zaman doğrudur?', 'Denge konumuna doğrudur', ['Hareket yönüyle aynıdır', 'Uzanım vektörüyle aynı yönlüdür', 'Hız vektörüne daima diktir'], 'Geri çağırıcı kuvvet cisim nereye giderse gitsin daima denge (merkez) noktasına yöneliktir.'),
  ('Uç noktalar arasında basit harmonik hareket yapan bir cisim genlik noktasına ulaştığında hangi niceliği en büyük değerini alır?', 'İvme büyüklüğü', ['Çizgisel sürati', 'Kinetik enerjisi', 'Anlık momentumu'], 'Genlik (uç) noktalarında uzanım maksimum olduğundan ivme ve geri çağırıcı kuvvet maksimum, hız ise sıfırdır.'),
  ('K ve L noktaları arasında 12 saniye periyotla basit harmonik hareket yapan bir cisim, bir uç noktadan denge konumuna en az kaç saniyede gelir?', '3 saniye', ['4 saniye', '6 saniye', '2 saniye'], 'Bir uç noktadan denge noktasına geliş süresi periyodun dörtte biridir: T/4 = 12/4 = 3 saniyedir.'),
  ('Basit harmonik harekette uzanım (x) ile ivme (a) arasındaki vektörel bağıntı aşağıdakilerden hangisidir?', 'a = -ω²·x', ['a = +ω²·x', 'a = -ω·x²', 'a = +ω·x'], 'İvme vektörü uzanım vektörüyle zıt yönlü olduğundan önünde eksi işareti bulunur ve açısal frekansın karesiyle çarpan alır.'),
  ('Frekansı 0,5 Hz olan basit harmonik hareketlinin açısal hızı kaç rad/s\'dir? (π = 3 alınız.)', '3 rad/s', ['6 rad/s', '1,5 rad/s', '12 rad/s'], 'ω = 2·π·f bağıntısından ω = 2 · 3 · 0,5 = 3 rad/s bulunur.'),
  ('Genliği 0,4 m ve açısal hızı 5 rad/s olan basit harmonik hareketlinin maksimum hızı kaç m/s\'dir?', '2 m/s', ['1,25 m/s', '10 m/s', '0,8 m/s'], 'Maksimum hız denge konumunda gerçekleşir ve v_maks = ω·r = 5 · 0,4 = 2 m/s olarak hesaplanır.'),
  ('Basit harmonik harekette kuvvet-uzanım grafiğinin eğim büyüklüğü hangi fiziksel niceliği verir?', 'Kuvvet sabitini (k = m·ω²)', ['Cismin kütlesini (m değeri)', 'Maksimum hızı (ω·r çarpımı)', 'Salınım periyodunu (T süresi)'], 'F = -k·x bağıntısına göre kuvvetin uzanıma oranı geri çağırıcı kuvvet sabitini verir.'),
  ('Bir cismin basit harmonik hareket yapabilmesi için üzerine etki eden net kuvvetin özelliği ne olmalıdır?', 'Uzanımla doğru orantılı ve zıt yönlü olmalıdır', ['Hızla doğru orantılı ve aynı yönlü olmalıdır', 'Uzanımın karesiyle ters orantılı olmalıdır', 'Hareket boyunca büyüklüğü ve yönü sabit kalmalıdır'], 'Hooke yasası formunda (F = -k·x) uzanımla orantılı ve dengeye çağırıcı net kuvvet basit harmonik hareketin temel şartıdır.'),
  ('Kütlesi 2 kg olan bir cisim, açısal hızı 4 rad/s olan basit harmonik hareket yapmaktadır. Cismin uzanımı 0,5 m olduğu anda geri çağırıcı kuvvetin büyüklüğü kaç N olur?', '16 N', ['8 N', '32 N', '4 N'], 'F = m·ω²·x bağıntısından F = 2 · 4² · 0,5 = 2 · 16 · 0,5 = 16 N elde edilir.'),
  ('Uç noktaları arasındaki uzaklık 60 cm olan bir basit harmonik hareketlinin genliği kaç santimetredir?', '30 cm', ['60 cm', '15 cm', '120 cm'], 'İki uç nokta arası uzaklık 2r kadardır; 2r = 60 cm ise genlik r = 30 cm olur.'),
  ('Basit harmonik harekette uzanım vektörü ile hız vektörü arasındaki yön ilişkisi için ne söylenebilir?', 'Denge noktasından uzaklaşırken aynı, yaklaşırken zıt yönlüdür', ['Hareketin her anında birbirine zıt yönlüdürler', 'Hareketin her anında birbirleriyle aynı yönlüdürler', 'Yalnızca uç noktalarda aynı yönü gösterirler'], 'Uzanım daima dengeden dışarı doğrudur; cisim uç noktaya giderken hız da dışarı (aynı yön), dengeye dönerken hız içeri (zıt yön) doğrudur.'),
  ('Periyodu 24 saniye olan bir basit harmonik hareketli, denge konumundan harekete geçtikten sonra genliğin yarısına (r/2) ilk kez kaçıncı saniyede ulaşır?', '2. saniyede', ['3. saniyede', '4. saniyede', '6. saniyede'], 'Denge noktasından r/2 konumuna geçiş süresi T/12 kadardır; 24 / 12 = 2. saniyede ulaşır.'),
  ('Sürtünmesiz ortamda basit harmonik hareket yapan bir cismin genliği iki katına çıkarılırsa maksimum hızı ve periyodu nasıl değişir?', 'Maksimum hız iki katına çıkar, periyot değişmez', ['Hem maksimum hız hem de periyot iki katına çıkar', 'Maksimum hız değişmez, periyot yarıya iner', 'Maksimum hız dört katına çıkar, periyot iki katına çıkar'], 'Basit harmonik harekette periyot genliğe bağlı değildir; v_maks = ω·r olduğundan ω sabitken r iki katına çıkarsa maksimum hız da iki katına çıkar.'),
  ('Basit harmonik harekette birim zamandaki tam salınım sayısına ne ad verilir ve SI birimi nedir?', 'Frekans - Hertz (s⁻¹)', ['Periyot - Saniye (s)', 'Açısal hız - Radyan/saniye', 'Genlik - Metre (m)'], '1 saniyedeki salınım sayısına frekans denir, f ile gösterilir ve SI birimi Hertz (Hz = s⁻¹) olur.'),
  ('Esneklik sabiti k olan kütlesiz bir yayın ucuna m kütleli cisim bağlanarak oluşturulan yay sarkacının periyot bağıntısı aşağıdakilerden hangisidir?', 'T = 2π·√(m / k)', ['T = 2π·√(k / m)', 'T = 2π·√(L / g)', 'T = 2π·(m / k)'], 'İdeal yay sarkacının salınım periyodu T = 2π·√(m / k) bağıntısıyla bulunur ve yer çekimi ivmesinden bağımsızdır.'),
  ('Dünya yüzeyinde periyodu T olan bir yay sarkacı Ay yüzeyine götürülüp aynı genlikle salınıma bırakılırsa periyodu nasıl değişir? (Ay\'ın çekim ivmesi Dünya\'nınkinin yaklaşık altıda biridir.)', 'Değişmez, yine T olur', ['Altı katına çıkar', 'Kök altı katına çıkar', 'Altıda birine iner'], 'Yay sarkacının periyodu T = 2π·√(m/k) olup kütle ve yay sabiti çekim ivmesine bağlı olmadığından Ay\'da da periyot değişmez.'),
  ('Küçük açılarla (α ≤ 5°) salınım yapan L uzunluklu ideal bir basit sarkacın periyot formülü aşağıdakilerden hangisidir?', 'T = 2π·√(L / g)', ['T = 2π·√(g / L)', 'T = 2π·√(m·L / g)', 'T = 2π·(L / g)'], 'Küçük açılarda basit harmonik hareket yapan basit sarkacın periyodu T = 2π·√(L / g) bağıntısıyla hesaplanır.'),
  ('Küçük açılarla salınan bir basit sarkacın ucundaki m kütleli bilye çıkarılıp yerine aynı boyutlarda 4m kütleli demir bilye takılırsa sarkacın periyodu nasıl değişir? (Hava direnci önemsizdir.)', 'Değişmez', ['İki katına çıkar', 'Dört katına çıkar', 'Yarıya iner'], 'Basit sarkacın periyodu T = 2π·√(L/g) olup ucuna asılan kütleden bağımsızdır.'),
  ('Yay sabiti 100 N/m olan esnek bir yayın ucuna 4 kg kütleli cisim bağlanarak sürtünmesiz yatay düzlemde salınıma bırakılıyor. Yay sarkacının periyodu kaç saniyedir? (π = 3 alınız.)', '1,2 saniye', ['2,4 saniye', '0,6 saniye', '1,5 saniye'], 'T = 2π·√(m/k) = 2 · 3 · √(4 / 100) = 6 · (2 / 10) = 1,2 saniye bulunur.'),
  ('Yer çekimi ivmesinin 10 m/s² olduğu bir ortamda ip uzunluğu 40 cm olan basit sarkacın küçük genlikli salınım periyodu kaç saniyedir? (π = 3 alınız.)', '1,2 saniye', ['2,4 saniye', '0,6 saniye', '12 saniye'], 'L = 40 cm = 0,4 m için T = 2π·√(L/g) = 2 · 3 · √(0,4 / 10) = 6 · √(0,04) = 6 · 0,2 = 1,2 saniye olur.'),
  ('Yay sabitleri k₁ ve k₂ olan iki esnek yay paralel bağlandığında sistemin eşdeğer yay sabiti (k_eş) nasıl bulunur?', 'k_eş = k₁ + k₂', ['k_eş = (k₁·k₂) /', 'k_eş = |k₁ - k₂|', 'k_eş = √(k₁·k₂)'], 'Paralel bağlı yaylar aynı miktarda uzadığından toplam kuvvet ayrı kuvvetlerin toplamına eşit olur ve k_eş = k₁ + k₂ bulunur.'),
  ('Özdeş ve yay sabiti k olan iki yay uç uca (seri) bağlandığında sistemin eşdeğer yay sabiti kaç k olur?', 'k / 2', ['2k', 'k', 'k / 4'], 'Seri bağlı yaylarda 1/k_eş = 1/k + 1/k = 2/k olduğundan eşdeğer yay sabiti k/2 olur.'),
  ('Sürtünmesiz eğik düzlem üzerinde salınım yapan bir yay sarkacının eğik düzlemin eğim açısı artırılırsa salınım periyodu nasıl değişir?', 'Değişmez', ['Eğim açısının sinüsüyle doğru orantılı artar', 'Eğim açısının kosinüsüyle doğru orantılı azalır', 'Önce artar sonra sabit kalır'], 'Eğik düzlem açısı yalnızca denge uzama miktarını değiştirir; yay sarkacının periyodu T = 2π·√(m/k) olduğundan eğim açısından etkilenmez.'),
  ('Bir basit sarkacın periyodunu 3 katına çıkarmak için aynı ortamda ipinin boyu kaç katına çıkarılmalıdır?', '9 katına', ['3 katına', '√3 katına', '6 katına'], 'T = 2π·√(L/g) bağıntısına göre T ile √L doğru orantılıdır; T\'nin 3 katına çıkması için L\'nin 3² = 9 katına çıkması gerekir.'),
  ('Dünya\'da ekvatordan kutuplara doğru gidildikçe yer çekimi ivmesi hafifçe artmaktadır. Ekvatorda doğru çalışan sarkaçlı bir duvar saati kutuplara götürülürse nasıl çalışır? (Sıcaklık sabit tutulmaktadır.)', 'Periyodu küçülür ve saat ileri gider', ['Periyodu büyür ve saat geri kalır', 'Periyodu değişmez ve doğru çalışmaya devam eder', 'Sarkacın genliği sıfırlanarak tamamen durur'], 'Kutuplarda g arttığı için T = 2π·√(L/g) azalır; salınımlar daha kısa sürede tamamlandığından saat hızlanır ve ileri gider.'),
  ('Özdeş üç yay paralel bağlanıp uçlarına 3 kg kütleli bir cisim asıldığında periyot 2 saniye oluyor. Her bir yayın esneklik sabiti kaç N/m\'dir? (π = 3 alınız.)', '9 N/m', ['27 N/m', '3 N/m', '18 N/m'], 'T = 2π·√(m / 3k) => 2 = 6·√(3 / 3k) => 1/3 = √(1/k) => k = 9 N/m bulunur.'),
  ('Sabit hızla yukarı doğru çıkmakta olan bir asansörün tavanına asılı basit sarkacın periyodu, asansör durgunken ölçülen periyoduna göre nasıldır?', 'Değişmez, durgun haldekiyle aynıdır', ['Asansör yukarı çıktığı için azalır', 'Asansör yukarı çıktığı için artar', 'Asansörün hızına bağlı olarak sürekli azalır'], 'Sabit hızlı harekette ivme sıfırdır (eylemsizlik etkisi yoktur); etkin çekim ivmesi yine g olduğundan periyot değişmez.'),
  ('Homojen ve esnek bir yay tam ortasından kesilerek iki eşit uzunluklu parçaya ayrılırsa, elde edilen her bir parçanın yay sabiti ilk yayın yay sabitinin kaç katı olur?', '2 katı', ['1 / 2 katı', '4 katı', '1 katı'], 'Bir yayın boyu ile yay sabiti ters orantılıdır (k·L = sabit); boy yarıya inince yay sertleşir ve yay sabiti 2k olur.'),
  ('Periyodu T olan bir yay sarkacının ucundaki kütle 4 katına çıkarılıp yay sabiti yarıya indirilirse yeni periyot kaç T olur?', '2√2 · T', ['2 · T', '8 · T', '√2 · T'], 'T\' = 2π·√(4m / (k/2)) = 2π·√(8m / k) = √8 · T = 2√2 · T olarak bulunur.'),
  ('Saniyeleri vuran basit sarkaç tabiri fizikte periyodu kaç saniye olan sarkaçlar için kullanılır?', 'Periyodu 2 saniye olan sarkaçlar için', ['Periyodu 1 saniye olan sarkaçlar için', 'Periyodu 0,5 saniye olan sarkaçlar için', 'Periyodu 60 saniye olan sarkaçlar için'], 'Saniyeleri vuran sarkaç bir uçtan diğer uca (yarım salınım, T/2) 1 saniyede gider; dolayısıyla tam periyodu T = 2 saniyedir.'),
  ('Yukarı yönde 6 m/s² sabit ivmeyle hızlanan bir asansörün tavanına asılı 1 metre boyundaki basit sarkacın periyodu kaç saniyedir? (g = 10 m/s², π = 3 alınız.)', '1,5 saniye', ['3 saniye', '2 saniye', '1,2 saniye'], 'Yukarı hızlanan asansörde etkin çekim ivmesi g_etkin = g + a = 10 + 6 = 16 m/s² olur. T = 2 · 3 · √(1 / 16) = 6 / 4 = 1,5 saniye bulunur.'),
  ('Aşağı yönde yer çekimi ivmesine eşit (a = g) ivmeyle serbest düşme yapan bir kabinin tavanına asılı basit sarkaç denge konumundan hafifçe çekilip bırakılırsa nasıl hareket eder?', 'Salınım yapmaz, bırakıldığı konumda kabine göre hareketsiz kalır', ['Durgun ortamdakinden iki kat daha küçük periyotla hızla salınır', 'Durgun ortamdakiyie tamamen aynı periyotta salınım yapar', 'Düşey düzlemde sabit açısal hızla tam çembersel hareket yapar'], 'Serbest düşen kabinde g_etkin = g - g = 0 olur; geri çağırıcı kuvvet oluşmadığından sarkaç bırakıldığı açıda ağırlıksız gibi asılı kalır (periyot sonsuzdur).'),
  ('Sürtünmesiz yatay düzlemde iki duvar arasına gerilmiş k₁ ve k₂ yaylarının ortasına bağlanan m kütleli cismin salınım hesabında yayların bağlanma şekli aşağıdakilerden hangisidir?', 'Paralel bağlı (k_eş = k₁ + k₂)', ['Seri bağlı (1/k_eş = 1/k₁ + 1/k₂)', 'Yalnızca büyük yay sabitli yaya bağlı', 'Farkları alınarak bağlı (|k₁ - k₂|)'], 'Cisim bir tarafa x kadar çekildiğinde yaylardan biri x kadar uzarken diğeri x kadar sıkışır ve her ikisi de cismi aynı yönde merkeze çağırır; bu yüzden paralel bağlıdırlar.'),
  ('Aynı ortamda bulunan K ve L basit sarkaçlarının periyotları oranı T_K / T_L = 1 / 4 olduğuna göre, sarkaçların ip boyları oranı L_K / L_L kaçtır?', '1 / 16', ['1 / 2', '1 / 4', '1 / 8'], 'T_K / T_L = √(L_K / L_L) = 1/4 olduğundan her iki tarafın karesi alındığında L_K / L_L = 1/16 bulunur.'),
  ('Küçük açılarla salınan bir basit sarkaçta cismi denge konumuna geri çağıran net teğetsel kuvvetin büyüklüğü aşağıdakilerden hangisidir? (θ: düşeyle yapılan açı)', 'm·g·sin(θ)', ['m·g·cos(θ)', 'm·g·tan(θ)', 'm·g'], 'İp doğrultusuna dik olan ve cismi dengeye çağıran ağırlık bileşeni m·g·sin(θ) olup küçük açılarda sin(θ) ≈ x/L yaklaşıklığıyla BHH üretir.'),
  ('Düşeyde asılı esnek bir yaya m kütleli cisim bağlanıp dengeye geldiğinde yay 90 cm uzamaktadır. Bu cisim denge konumundan biraz daha çekilip bırakılırsa yapacağı basit harmonik hareketin periyodu kaç saniye olur? (g = 10 m/s², π = 3 alınız.)', '1,8 saniye', ['2,4 saniye', '0,9 saniye', '1,2 saniye'], 'Denge şartından m·g = k·Δx => m/k = Δx/g = 0,9 / 10 = 0,09 s² bulunur; T = 2π·√(m/k) = 6 · 0,3 = 1,8 saniye olur.'),
  ('Basit harmonik harekette cismin denge konumundan ulaşabildiği en büyük uzaklık hangi kavramla ifade edilir?', 'Genlik', ['Salınım periyodu', 'Açısal hız vektörü', 'Anlık uzanım değeri'], 'Cismin salınım sırasında denge noktasına göre eriştiği maksimum uzaklık genliktir.'),
  ('Sürtünmesiz ortamda basit harmonik hareket yapan bir cismin bir tam salınımı tamamlaması için geçen süreye ne denir?', 'Periyot', ['Salınım frekansı', 'Açısal frekans', 'Maksimum genlik'], 'Bir tam gidiş geliş hareketinin tamamlanma süresi periyot olarak adlandırılır.'),
  ('Basit harmonik harekette geri çağırıcı kuvvetin yönü her zaman nereye doğrudur?', 'Denge konumuna', ['Hareketin anlık hızına', 'En uzak genlik noktasına', 'Sürtünme kuvvetinin yönüne'], 'Geri çağırıcı kuvvet cismi sürekli denge noktasına geri çekmeye çalıştığı için yönü daima denge konumunadır.'),
  ('Sürtünmesiz yatay düzlemde yay ucunda basit harmonik hareket yapan bir cismin ivmesi hangi konumda maksimum büyüklüğe ulaşır?', 'Uç genlik noktalarında', ['Denge noktasının merkezinde', 'Kinetik enerjinin zirvesinde', 'Hızın en büyük olduğu noktada'], 'İvme uzanımla doğru orantılı olduğundan uzanımın genliğe eşit olduğu uç noktalarda ivme maksimumdur.'),
  ('Yatay sürtünmesiz düzlemdeki bir yay-kütle sisteminin periyodu aşağıdaki niceliklerden hangisine bağlı değildir?', 'Salınım genliğine', ['Yayın esneklik sabitine', 'Bağlı cismin kütlesine', 'Yayların bağlanma şekline'], 'Yay-kütle sarkacının periyodu T = 2π√(m/k) bağıntısıyla bulunur ve genlikten bağımsızdır.'),
  ('Küçük açılarla salınan bir basit sarkacın periyodu aşağıdakilerden hangisine bağlı değildir?', 'Sarkaç ucundaki kütleye', ['İpin toplam uzunluğuna', 'Yerçekimi ivmesinin büyüklüğüne', 'Bulunulan gezegenin kütlesine'], 'Basit sarkacın periyodu T = 2π√(L/g) olduğundan ucundaki cismin kütlesi periyodu değiştirmez.'),
  ('Yerçekimi ivmesinin daha küçük olduğu Ay yüzeyine götürülen bir basit sarkacın salınım periyodu Dünya\'dakine göre nasıl değişir?', 'Artar', ['Azalır', 'Sabit kalır', 'Sıfıra düşer'], 'Periyot T = 2π√(L/g) bağıntısında g ile ters orantılı olduğundan Ay\'da yerçekimi küçüldüğü için periyot artar.'),
  ('Yatay sürtünmesiz düzlemdeki bir yay-kütle sarkacı Dünya\'dan Ay yüzeyine götürülürse salınım periyodu nasıl değişir?', 'Değişmez', ['İki katına çıkar', 'Yaklaşık altı kat artar', 'Yarı değerine iner'], 'Yay sarkacının periyodu yerçekimi ivmesine bağlı olmadığı için Ay\'da da aynı kalır.'),
  ('Esneklik sabiti k olan özdeş iki yay birbirine paralel bağlandığında eşdeğer yay sabiti kaç k olur?', '2k', ['0,5k', '4k', '1k'], 'Paralel bağlı yaylarda eşdeğer yay sabiti yay sabitlerinin doğrudan toplamına eşit olduğundan k + k = 2k elde edilir.'),
  ('Esneklik sabiti k olan özdeş iki yay uç uca seri bağlandığında sistemin eşdeğer yay sabiti ne olur?', 'k/2', ['2k', '3k', '4k'], 'Seri bağlı özdeş iki yayda 1/k_eş = 1/k + 1/k bağıntısından eşdeğer yay sabiti k/2 bulunur.'),
  ('Bir yayın boyu tam ortasından kesilerek yarıya indirilirse elde edilen her bir parçanın yay sabiti ilk duruma göre nasıl değişir?', 'İki katına çıkar', ['Yarı değerine iner', 'Dört katına çıkar', 'İlk değeriyle aynı kalır'], 'Yay sabiti yayın uzunluğuyla ters orantılı olduğu için boy yarıya indiğinde esneklik sabiti iki katına çıkar.'),
  ('Saniyede 4 tam salınım yapan bir harmonik osilatörün periyodu kaç saniyedir?', '0,25 s', ['0,50 s', '2,00 s', '4,00 s'], 'Frekans 4 Hz olduğundan periyot T = 1/f = 1/4 = 0,25 s olarak hesaplanır.'),
  ('Sürtünmesiz basit harmonik harekette cisim denge konumundan uzaklaşırken kinetik enerjisi ve potansiyel enerjisi nasıl değişir?', 'Kinetik azalır, potansiyel artar', ['Kinetik artar, potansiyel azalır', 'İki enerji türü de birlikte artar', 'İki enerji türü de sabit kalır'], 'Denge noktasından uzaklaşırken cisim yavaşlar, böylece kinetik enerjisi azalırken esneklik veya çekim potansiyel enerjisi artar.'),
  ('Dışarıdan uygulanan periyodik bir kuvvetin frekansı sistemin doğal salınım frekansına eşit olduğunda genliğin maksimuma çıkması olayına ne ad verilir?', 'Rezonans', ['Sönümlenme', 'Kırınım olayı', 'Girişim deseni'], 'Zorlayıcı frekansın doğal frekansla çakışması sonucu sistemin maksimum enerji soğurup büyük genlikle salınması rezonanstır.'),
  ('Hava direnci ve iç sürtünmeler nedeniyle salınım genliğinin zamanla azalarak hareketin durmasına neden olan salınım türü hangisidir?', 'Sönümlü salınım', ['Zorlamalı salınım', 'Serbest harmonik hareket', 'Eşzamanlı salınım'], 'Sürtünme kuvvetlerinin mekanik enerjiyi ısıya dönüştürerek genliği sürekli küçülttüğü salınımlar sönümlü salınım olarak adlandırılır.'),
  ('İki noktasal kütle arasındaki evrensel kütleçekim kuvvetinin büyüklüğü aralarındaki uzaklıkla nasıl değişir?', 'Uzaklığın karesiyle ters orantılıdır', ['Uzaklığın kendisiyle ters orantılıdır', 'Uzaklığın karesiyle doğru orantılıdır', 'Uzaklığın küpüyle ters orantılıdır'], 'Newton\'un evrensel kütleçekim yasasına göre F = G·m₁·m₂/r² olduğundan kuvvet uzaklığın karesiyle ters orantılıdır.'),
  ('Evrensel kütleçekim yasasına göre iki cismin kütleleri sabit tutulup aralarındaki uzaklık iki katına çıkarılırsa çekim kuvveti nasıl değişir?', 'Dörtte birine iner', ['Yarı değerine iner', 'İki katına çıkar', 'Dört katına çıkar'], 'Kuvvet uzaklığın karesiyle ters orantılı olduğu için r değeri 2r yapıldığında kuvvet F/4 olur.'),
  ('Kepler\'in birinci yasasına göre Güneş Sistemi\'ndeki her gezegen Güneş etrafında nasıl bir yörüngede dolanır?', 'Bir odağında Güneş bulunan elips', ['Merkezinde Güneş bulunan çember', 'Odakları çakışan bir parabol', 'Düzlem dışı sarmal eğri'], 'Kepler\'in Yörüngeler Yasası\'na göre gezegenler odaklarından birinde Güneş\'in yer aldığı eliptik yörüngelerde hareket eder.'),
  ('Kepler\'in ikinci yasasına göre Güneş\'i gezegene birleştiren yarıçap vektörü eşit zaman aralıklarında ne tarar?', 'Eşit alanlar', ['Eşit yay uzunlukları', 'Eşit açısal mesafeler', 'Eşit doğrusal yollar'], 'Alanlar Yasası olarak bilinen ikinci yasaya göre yarıçap vektörü eşit sürelerde eşit alanlar süpürür.'),
  ('Eliptik yörüngede dolanan bir gezegen Güneş\'e en yakın olduğu günberi konumundan geçerken çizgisel sürati nasıl olur?', 'En büyük değerini alır', ['En küçük değerini alır', 'Ortalama süratine düşer', 'Anlık olarak sıfırlanır'], 'Açısal momentum korunduğu ve yarıçap en küçük olduğu için gezegen günberi noktasında en hızlı hareket eder.'),
  ('Dünya\'nın yüzeyinden fırlatılan bir cismin kütleçekim alanından tamamen kurtularak sonsuza ulaşabilmesi için gereken minimum başlangıç hızına ne ad verilir?', 'Kaçış hızı', ['Yörünge hızı', 'Kritik dönme hızı', 'Eşzamanlı dolanım hızı'], 'Toplam mekanik enerjiyi sıfır yaparak cismin gezegenin çekim kuyusundan çıkmasını sağlayan en küçük hız kaçış hızıdır.'),
  ('Dünya\'nın kendi ekseni etrafındaki dönüş periyoduyla aynı periyoda sahip olup ekvator üzerinde sabit bir nokta üstünde duruyormuş gibi görünen yörünge hangisidir?', 'Yer eşzamanlı sabit yörünge', ['Alçak kutup gözlem yörüngesi', 'Güneş eşzamanlı transfer yörüngesi', 'Eliptik Molniya haberleşme yörüngesi'], 'Ekvator düzleminde 24 saatlik periyotla doğuya doğru dolanan uydular yer sabit (jeostatik) yörüngede gökyüzünde sabit görünür.'),
  ('Basit harmonik harekette birim zamanda gerçekleşen tam salınım sayısına ne ad verilir?', 'Frekans', ['Salınım periyodu', 'Maksimum genlik', 'Geri çağırıcı kuvvet'], 'Bir saniyede tamamlanan salınım sayısı frekans olarak tanımlanır ve birimi hertz\'dir (Hz).'),
  ('Hooke yasasına göre ideal bir yayın uyguladığı geri çağırıcı kuvvetin büyüklüğü yayın uzama veya sıkışma miktarıyla nasıl ilişkilidir?', 'Doğru orantılıdır', ['Ters orantılıdır', 'Karesiyle orantılıdır', 'Kareköküyle orantılıdır'], 'Hooke yasası F = -k·x şeklinde olup kuvvetin büyüklüğü uzama miktarıyla doğrusal olarak artar.'),
  ('Evrensel kütleçekim sabiti G\'nin uluslararası birim sistemindeki (SI) birimi aşağıdakilerden hangisidir?', 'N·m²/kg²', ['N·kg²/m²', 'N·m/kg²', 'kg·m/s²'], 'F = G·m₁·m₂/r² denkleminden G = F·r²/(m₁·m₂) elde edilir ve birimi N·m²/kg² olur.'),
  ('Kütleçekim potansiyel enerjisi hesaplanırken gök mekaniğinde sıfır referans düzeyi geleneksel olarak nerede seçilir?', 'Sonsuz uzaklıkta', ['Gezegenin merkezinde', 'Gezegenin yüzeyinde', 'Yörünge odak noktasında'], 'U = -GMm/r ifadesinde r sonsuza giderken potansiyel enerji sıfır olur; bu yüzden sonsuzluk referans alınır.'),
  ('Dünya\'nın yüzeyinden uzaklaştıkça bir cismin üzerindeki kütleçekim kuvveti ve cismin kütlesi nasıl değişir?', 'Kuvvet azalır, kütle değişmez', ['Hem kuvvet hem kütle azalır', 'Kuvvet değişmez, kütle azalır', 'Hem kuvvet hem kütle artar'], 'Kütle madde miktarıdır ve konuma göre değişmez; çekim kuvveti ise merkezden uzaklaştıkça 1/r² oranında azalır.'),
  ('Eliptik bir yörüngede gezegenin Güneş\'e en uzak olduğu konuma ne ad verilir?', 'Günöte', ['Günberi', 'Ekinoks noktası', 'Düğüm noktası'], 'Gezegenin Güneş etrafındaki eliptik yörüngesinde Güneş\'e maksimum mesafede bulunduğu uç nokta günötedir.'),
  ('Bir basit sarkacın salınım periyodunu iki katına çıkarmak için sarkaç ipinin uzunluğu ilk değerinin kaç katına çıkarılmalıdır?', '4', ['2', '8', '16'], 'T = 2π√(L/g) bağıntısında periyodun 2 kat artması için karekök içindeki ip uzunluğu 4 katına çıkarılmalıdır.'),
  ('Bir yayın ucuna bağlı kütlenin salınım periyodunu yarıya indirmek için kütlenin değeri ilk halinin kaçta kaçına düşürülmelidir?', '1/4', ['1/2', '1/8', '1/16'], 'T = 2π√(m/k) olduğundan periyodun yarıya inmesi için kütlenin dörtte birine düşürülmesi gerekir.'),
  ('Bir yapay uyduyu Dünya\'nın yüzeyinden fırlatmak yerine ekvatordan doğu yönüne doğru fırlatmanın sağladığı temel avantaj nedir?', 'Dünya\'nın kendi eksenindeki dönüş hızından yararlanmak', ['Kutup bölgelerindeki yoğun manyetik alandan kaçınmak', 'Ekvatorda atmosferin hiç bulunmamasından yararlanmak', 'Ekvatorda yerçekimi ivmesinin tamamen sıfır olması'], 'Dünya batıdan doğuya doğru döndüğü için ekvatorda yaklaşık 465 m/s\'lik başlangıç teğetsel hızı roketin yakıt gereksinimini azaltır.'),
  ('Bir müzik aletinin telini titreştirdiğimizde aynı doğal frekansa sahip yakındaki başka bir telin de kendiliğinden titreşmeye başlaması hangi olaya örnektir?', 'Akustik rezonans', ['Kırılma olayı', 'Doppler kayması', 'Aşırı sönümlenme'], 'İlk telin yaydığı ses dalgalarının frekansı ikinci telin doğal frekansıyla örtüştüğünde enerji aktarımı maksimuma çıkar ve rezonans oluşur.'),
  ('Sürtünmesiz bir sistemde basit harmonik hareket yapan bir cismin bir tam periyodu boyunca hızının yönü kaç kez değişir?', '2 kez', ['1 kez', '3 kez', '4 kez'], 'Cisim bir tam salınımda her iki uç dönüş noktasından birer kez geçerek hız yönünü toplam iki defa tersine çevirir.'),
  ('Dünya\'nın merkezinden geçecek biçimde yerin içine inildikçe ideal homojen bir gezegende çekim ivmesi merkeze tam ulaşıldığında hangi değeri alır?', 'Sıfır', ['Yüzeydeki g değerini', 'Yüzeydeki değerin iki katını', 'Sonsuz büyük bir değeri'], 'Tam merkezde çevredeki tüm kütle elemanlarının çekim kuvvetleri simetrik olarak birbirini götürdüğü için net çekim ivmesi sıfırdır.'),
  ('Aynı eksende dolanan bir gezegenin yarıçap vektörü belirli bir zaman diliminde ne kadar büyük alan tarıyorsa o gezegenin hangi niceliği o kadar büyüktür?', 'Açısal momentumu', ['Kütleçekim potansiyeli', 'Dış merkezlik değeri', 'Yüzey sıcaklık farkı'], 'Kepler\'in ikinci yasasında alansal hız dA/dt = L/(2m) olduğundan birim zamanda taranan alan açısal momentumla doğru orantılıdır.'),
  ('Yer sabit (jeostatik) haberleşme uydularının Dünya\'nın kutup bölgelerine değil ekvator düzlemine yerleştirilmesinin temel nedeni nedir?', 'Yörünge merkezinin Dünya\'nın merkeziyle çakışması zorunluluğu', ['Kutuplarda Güneş panellerinin hiç enerji üretememesi', 'Kutuplar üzerinde uzay boşluğunun daha soğuk olması', 'Ekvator üzerinde hava sürtünmesinin yörüngeyi hızlandırması'], 'Bir uydunun yörünge düzlemi daima Dünya merkezinden geçmelidir; yalnızca ekvator düzleminde dönen 24 saatlik uydu yerdeki bir nokta üstünde sabit kalabilir.'),
  ('Uluslararası Uzay İstasyonu\'nun içindeki astronotların ağırlıksız görünmesinin (mikro yerçekimi) gerçek fiziksel sebebi aşağıdakilerden hangisidir?', 'İstasyon ve astronotların Dünya\'ya doğru sürekli serbest düşmesi', ['İstasyon yüksekliğinde Dünya\'nın kütleçekiminin sıfıra inmesi', 'İstasyonun özel manyetik kalkanla yerçekimini engellemesi', 'Ay\'ın çekim kuvvetinin Dünya\'nın çekimini tam dengelemesi'], '400 km yükseklikte yerçekimi yüzeyin yaklaşık %89\'udur; astronotlar istasyonla aynı merkezcil ivmeyle serbest düştükleri için ağırlıksızlık hisseder.'),
  ('Sürtünmesiz yatay yay-kütle sisteminde cisim denge konumundan geçerken yaya etkiyen net esneklik kuvveti kaç newtondur?', '0 N', ['k·A kadar', 'm·g kadar', '(1/2)k·A² kadar'], 'Denge konumunda yayın uzama miktarı x = 0 olduğundan Hooke yasasına göre geri çağırıcı kuvvet sıfırdır.'),
  ('Güneş Sistemi\'nde yörünge periyotlarının karelerinin yarı büyük eksenlerinin küplerine oranının (T²/a³) tüm gezegenler için sabit olduğunu belirten yasa hangisidir?', 'Kepler\'in üçüncü yasası', ['Kepler\'in birinci yasası', 'Kepler\'in ikinci yasası', 'Hooke\'un esneklik yasası'], 'Harmonikler Yasası olarak da bilinen Kepler\'in üçüncü yasası aynı merkez cisim etrafındaki tüm yörüngeler için T²/a³ oranının sabitliğini ifade eder.'),
  ('Bir salıncakta sallanan çocuğu en verimli biçimde daha yükseğe çıkarmak için itme kuvveti hangi sıklıkla uygulanmalıdır?', 'Salıncağın doğal frekansına eşit sıklıkta', ['Salıncağın doğal frekansının üç katı sıklıkta', 'Rastgele ve düzensiz zaman aralıklarında', 'Çocuk en üst noktaya çıkmadan tam ters yönde'], 'Zorlayıcı kuvvet salıncağın doğal salınım frekansıyla aynı fazda ve frekansta uygulandığında rezonans sağlanır ve genlik hızla büyür.'),
];
